import itertools

def fast(p):
 n=len(p); y=[n+1]+list(p)+[0]; d=[1]+[0]*(n+1)
 for j in range(1,n+2):
  for i in range(j):
   if y[i]<=y[j]:continue
   v=[a for a in y[i+1:j] if y[j]<a<y[i]]
   if any(all(a>b for a in v[:k]) and all(a<b for a in v[k+1:]) for k,b in enumerate(v)):continue
   d[j]+=d[i]
 return d[-1]
def brute(p):
 n=len(p); nei=[sum(1<<j for j in range(n) if (i-j)*(p[i]-p[j])>0) for i in range(n)]
 seen={(1<<n)-1}; stack=list(seen)
 while stack:
  s=stack.pop()
  for i in range(n):
   if s>>i&1:
    t=s&~nei[i]
    if t not in seen:seen.add(t);stack.append(t)
 return len(seen)
for n in range(1,8):
 for p in itertools.permutations(range(1,n+1)):
  assert fast(p)==brute(p),p
 print(n,'ok')

