import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]

    # bad[r][x]: largest left endpoint of a condition at x
    # whose right endpoint is at most r.
    bad = [[-1] * n for _ in range(n)]
    for i in range(2, 2 + 3 * m, 3):
        l = data[i] - 1
        r = data[i + 1] - 1
        x = data[i + 2] - 1
        if l == r:
            print(0)
            return
        if l > bad[r][x]:
            bad[r][x] = l

    for r in range(1, n):
        row, prev = bad[r], bad[r - 1]
        for x in range(n):
            if prev[x] > row[x]:
                row[x] = prev[x]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the interval count divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1

    for r in range(n):
        col = [0] * (n + 1)
        col[r + 1] = 1
        bounds = bad[r]
        for l in range(r, -1, -1):
            row = dp[l]
            total = 0
            for k in range(l, r + 1):
                if bounds[k] < l:
                    total += row[k] * col[k + 1]
            value = total % MOD * inv[r - l + 1] % MOD
            row[r + 1] = value
            col[l] = value

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)


if __name__ == '__main__':
    main()

