import sys
from collections import deque

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    degree = [0] * n
    for v in a:
        degree[v] += 1
    q = deque(i for i in range(n) if degree[i] == 0)
    dp = [None] * n
    while q:
        u = q.popleft()
        v = a[u]
        row = dp[u]
        parent = dp[v]
        if row is None:
            if parent is None:
                dp[v] = list(range(1, m + 1))
            else:
                for j in range(m):
                    parent[j] = parent[j] * (j + 1) % MOD
        else:
            total = 0
            if parent is None:
                for j in range(m):
                    total += row[j]
                    if total >= MOD:
                        total -= MOD
                    row[j] = total
                dp[v] = row
            else:
                for j in range(m):
                    total += row[j]
                    if total >= MOD:
                        total -= MOD
                    parent[j] = parent[j] * total % MOD
        dp[u] = None
        degree[v] -= 1
        if degree[v] == 0:
            q.append(v)

    answer = 1
    for start in range(n):
        if degree[start] == 0:
            continue
        acc = None
        u = start
        while degree[u]:
            degree[u] = 0
            row = dp[u]
            if row is not None:
                if acc is None:
                    acc = row
                else:
                    for j in range(m):
                        acc[j] = acc[j] * row[j] % MOD
            dp[u] = None
            u = a[u]
        ways = m if acc is None else sum(acc) % MOD
        answer = answer * ways % MOD
    print(answer)

if __name__ == '__main__':
    main()

