import sys
from math import gcd
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for idx, value in enumerate(data[1:]):
        p = 2
        while p * p <= value:
            if value % p == 0:
                e = 0
                while value % p == 0:
                    value //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][idx] = e
            p += 1
        if value > 1:
            if value not in factors:
                factors[value] = [0] * (n - 1)
            factors[value][idx] = 1
    ans = 1
    for p, exponents in factors.items():
        g = 0
        for e in exponents:
            g = gcd(g, e)
        if g > 1:
            p = pow(p, g, MOD)
            exponents = [e // g for e in exponents]
        total = sum(exponents)
        powers = [1] * (total + 1)
        for j in range(1, total + 1):
            powers[j] = powers[j-1] * p % MOD
        dp = [1]
        for i, e in enumerate(exponents, 1):
            if e == 0:
                dp = [v * powers[h] % MOD for h, v in enumerate(dp)]
                continue
            size = len(dp)
            if size >= 2 * e:
                ndp = [dp[h+e] * powers[h] % MOD for h in range(e)]
                ndp.extend((dp[h-e] + dp[h+e]) * powers[h] % MOD for h in range(e, size-e))
                ndp.extend(dp[h-e] * powers[h] % MOD for h in range(size-e, size+e))
            else:
                ndp = [0] * (size + e)
                for h, v in enumerate(dp):
                    ndp[h + e] = v * powers[h + e] % MOD
                for h in range(e, size):
                    j = h - e
                    ndp[j] = (ndp[j] + dp[h] * powers[j]) % MOD
            base = pow(p, i, MOD)
            weight = base
            for h in range(e - 1, -1, -1):
                if h < size:
                    ndp[0] = (ndp[0] + dp[h] * weight) % MOD
                weight = weight * base % MOD
            dp = ndp
        ans = ans * (sum(dp) % MOD) % MOD
    print(ans)

if __name__ == '__main__':
    main()

