import sys
from math import isqrt

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:1 + data[0]]
    m = max(a)
    spf = list(range(m + 1))
    for p in range(2, isqrt(m) + 1):
        if spf[p] == p:
            for j in range(p * p, m + 1, p):
                if spf[j] == j:
                    spf[j] = p
    omega = bytearray(m + 1)
    for x in range(2, m + 1):
        omega[x] = omega[x // spf[x]] + 1
    result = 0
    for x in a:
        result ^= omega[x]
    print('Anna' if result else 'Bruno')

