import sys
from functools import lru_cache


def main():
    A, B, M = map(int, sys.stdin.buffer.read().split())
    # Complementing a permutation exchanges LIS and LDS.
    if A < B:
        A, B = B, A

    base = A + 1
    powers = [base ** i for i in range(B)]
    target = sum(A * powers[i] for i in range(B - 1)) + (A - 1) * powers[-1]

    # Count insertion tableaux of the rectangle minus its bottom-right
    # cell that admit an insertion into that missing cell.
    @lru_cache(None)
    def dp(state):
        if state == target:
            return 1
        remaining = state
        previous = A
        answer = 0
        for row in range(B):
            remaining, length = divmod(remaining, base)
            if length < previous:
                if length < A - 1 or (
                    row < B - 1 and remaining % base >= A - 1
                ):
                    answer += dp(state + powers[row])
            previous = length
        return answer % M

    insertion_count = dp(0)

    # The rectangle has one removable corner, so its number of standard
    # tableaux equals that of the rectangle with this corner removed.
    factorial = 1
    for value in range(1, A * B + 1):
        factorial = factorial * value % M
    hook_product = 1
    for row in range(B):
        for col in range(A):
            hook_product = hook_product * (A + B - row - col - 1) % M
    recording_count = factorial * pow(hook_product, M - 2, M) % M
    print(insertion_count * recording_count % M)


if __name__ == '__main__':
    main()

