import sys
from math import gcd

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    processes = []
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        if p * b > q * a:
            a, p, b, q = b, q, a, p
        options = [(j * b, j * q) for j in range(a // gcd(a, b))]
        processes.append((a, p, options))

    def feasible(w):
        total = 0
        for a, p, options in processes:
            best = ((w + a - 1) // a) * p
            for capacity, cost in options:
                remaining = w - capacity
                if remaining > 0:
                    cost += ((remaining + a - 1) // a) * p
                if cost < best:
                    best = cost
                if remaining <= 0:
                    break
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

