class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)
        steps = [0] * (length + 1)
        for c in range(2, length + 1):
            steps[c] = 1 + steps[c.bit_count()]

        # Count strictly smaller prefixes by their number of set bits.
        dp = [0] * (length + 1)
        ones = 0
        for i, bit in enumerate(s):
            for c in range(i + 1, 0, -1):
                dp[c] = (dp[c] + dp[c - 1]) % MOD
            if bit == '1':
                # Choose zero after a prefix equal to the bound.
                dp[ones] = (dp[ones] + 1) % MOD
                ones += 1

        return sum(dp[c] for c in range(1, length + 1)
                   if steps[c] < k) % MOD

