import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[:2]
    rows = [0] * n
    for i in range(m):
        u = data[2 + 2 * i] - 1
        v = data[3 + 2 * i] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form over GF(2).
    pivots = []
    rank = 0
    for c in range(n):
        bit = 1 << c
        p = next((i for i in range(rank, n) if rows[i] & bit), -1)
        if p == -1:
            continue
        rows[rank], rows[p] = rows[p], rows[rank]
        for i in range(n):
            if i != rank and rows[i] & bit:
                rows[i] ^= rows[rank]
        pivots.append(c)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    ans = [0] * n
    # Each free variable gets its own bit, encoding a full nullspace basis.
    for k, c in enumerate(free):
        ans[c] = 1 << k
    for i, c in enumerate(pivots):
        for f in free:
            if rows[i] & (1 << f):
                ans[c] ^= ans[f]

    # A zero coordinate here is zero in every vector in the nullspace.
    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)


if __name__ == '__main__':
    main()

