    for d in range(1, 1000001):
        d2 = d * d
        if d2 * d >= n:
            break
        if n % d:
            continue
        disc = 12 * (n // d) - 3 * d2
        s = isqrt(disc)
        if s * s == disc and s > 3 * d and (s - 3 * d) % 6 == 0:
            y = (s - 3 * d) // 6
            print(y + d, y)
            return
    print(-1)

