 r=sorted([v for x,y,v in zip(a,b,c) if x and not y],reverse=True)
 p=sorted([v for x,y,v in zip(a,b,c) if not x and y])
 q=sorted([v for x,y,v in zip(a,b,c) if x and y],reverse=True)
 s=sum(q);m=len(r)+len(p)
 cur=s*m+sum(i*v for i,v in enumerate(r))+sum((len(p)-i)*v for i,v in enumerate(p));ans=cur
 d=sorted(r+p);pre=[0]
