from collections import deque

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        a = nums[::-1]
        blocks = deque()
        left = 0
        cost = 0
        answer = 0
        for right, value in enumerate(a):
            while blocks and a[blocks[-1]] < value:
                end = blocks.pop()
                previous = blocks[-1] if blocks else left - 1
                cost += (end - previous) * (value - a[end])
            blocks.append(right)
            while cost > k:
                cost -= a[blocks[0]] - a[left]
                if blocks[0] == left:
                    blocks.popleft()
                left += 1
            answer += right - left + 1
        return answer

