from functools import cmp_to_key


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]
    counts = {}
    for i in range(2, 2 * n + 2, 2):
        pair = (data[i], data[i + 1])
        counts[pair] = min(k, counts.get(pair, 0) + 1)

    # Process functions from innermost to outermost, in increasing
    # order of (A - 1) / B. Cross multiplication keeps sorting exact.
    def compare(f, g):
        return (f[0] - 1) * g[1] - (g[0] - 1) * f[1]

    funcs = sorted(counts, key=cmp_to_key(compare))
    dp = [-1] * (k + 1)
    dp[0] = 1
    seen = 0
    for a, b in funcs:
        # No solution uses more than K copies of any function.
        for _ in range(counts[(a, b)]):
            seen += 1
            for j in range(min(k, seen), 0, -1):
                value = a * dp[j - 1] + b
                if value > dp[j]:
                    dp[j] = value
    print(dp[k])


