class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')
        la, lb, lc = len(a), len(b), len(c)
        if la + lb + lc > n:
            return -1

        def occurrences(t):
            m = len(t)
            if m == 0:
                return range(n + 1)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        j = k = 0
        answer = n + 1
        for start in aa:
            while j < len(bb) and bb[j] < start + la:
                j += 1
            if j == len(bb):
                break
            while k < len(cc) and cc[k] < bb[j] + lb:
                k += 1
            if k == len(cc):
                break
            answer = min(answer, cc[k] + lc - start)
        return answer if answer <= n else -1

