from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        start = [0] * n
        end = [0] * n
        chars = []
        stack = [0]
        while stack:
            x = stack.pop()
            if x >= 0:
                start[x] = len(chars)
                stack.append(~x)
                stack.extend(reversed(children[x]))
            else:
                x = ~x
                chars.append(s[x])
                end[x] = len(chars)

        text = '#' + '#'.join(chars) + '#'
        m = len(text)
        radius = [0] * m
        center = right = 0
        for i in range(m):
            if i < right:
                radius[i] = min(right - i, radius[2 * center - i])
            r = radius[i]
            while i - r - 1 >= 0 and i + r + 1 < m and text[i - r - 1] == text[i + r + 1]:
                r += 1
            radius[i] = r
            if i + r > right:
                center, right = i, i + r

        return [radius[start[i] + end[i]] >= end[i] - start[i] for i in range(n)]

