from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        bits = [1] * n
        targets = [1 << x for x in nums]
        masks = [(1 << (x + 1)) - 1 for x in nums]
        done = [x == 0 for x in nums]
        remaining = n - sum(done)
        if remaining == 0:
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if done[i]:
                    continue
                bits[i] = (bits[i] | (bits[i] << value)) & masks[i]
                if bits[i] & targets[i]:
                    done[i] = True
                    remaining -= 1
            if remaining == 0:
                return k
        return -1

