from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        # z[i] is the common prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            v = min(right - k, z[k - left]) if k < right else 0
            while k + v < n and nums[v] == nums[k + v]:
                v += 1
            z[k] = v
            if k + v > right:
                left, right = k, k + v

        # Count splits where the first part prefixes the second.
        answer = sum(
            n - 2 * i
            for i in range(1, (n + 1) // 2)
            if z[i] >= i
        )

        # Fix the second part's length and compute common prefixes
        # along this offset, scanning backwards.
        for length in range(1, (n - 1) // 2 + 1):
            common = 0
            for i in range(n - length - 1, 0, -1):
                if nums[i] == nums[i + length]:
                    common += 1
                    if common >= length and (length < i or z[i] < i):
                        answer += 1
                else:
                    common = 0
        return answer

