class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            v = min(right - k, z[k - left]) if k < right else 0
            while k + v < n and nums[v] == nums[k + v]:
                v += 1
            z[k] = v
            if k + v > right:
                left, right = k, k + v
        answer = 0
        for i in range(1, n - 1):
            limit = (n - i) // 2
            if z[i] >= i:
                answer += n - 2 * i
                limit = min(limit, i - 1)
            if limit == 0:
                continue
            zz = [0] * (limit + 1)
            left = right = 0
            size = n - i
            for k in range(1, limit + 1):
                v = min(right - k, zz[k - left]) if k < right else 0
                while k + v < size and nums[i + v] == nums[i + k + v]:
                    v += 1
                zz[k] = v
                if k + v > right:
                    left, right = k, k + v
                if v >= k:
                    answer += 1
        return answer

