class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        active = s.count('1')
        previous = 0
        best = 0
        for block in s.split('1'):
            length = len(block)
            if length:
                if previous:
                    best = max(best, previous + length)
                previous = length
        return active + best

