class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            letter = ord(ch) - ord('a')
            mirror_stack = stacks[25 - letter]
            if mirror_stack:
                score += i - mirror_stack.pop()
            else:
                stacks[letter].append(i)
        return score

